const RightTriangle: React.FC<{ scale: number; showLabels: boolean; a?: string; b?: string; c?: string; }> = ({ scale, showLabels, a, b, c }) => {
  const size = 300 * scale;
  const legA = 200 * scale;
  const legB = 150 * scale;

  // Coordinates for a right triangle with right angle at bottom-left
  const p1 = { x: 0, y: 0 }; // Bottom-left (Right angle)
  const p2 = { x: legA, y: 0 }; // Bottom-right
  const p3 = { x: 0, y: -legB }; // Top-left

  return (
    <svg width={size} height={size} viewBox={-50} style={{ overflow: 'visible' }}>
      {/* Triangle */}
      <polygon
        points={`${p1.x},${p1.y} ${p2.x},${p2.y} ${p3.x},${p3.y}`}
        fill="rgba(16, 185, 129, 0.1)"
        stroke={COLORS.text}
        strokeWidth={4 * scale}
      />

      {/* Right Angle Marker */}
      <path
        d={`M ${p1.x + 20 * scale} ${p1.y} L ${p1.x + 20 * scale} ${p1.y - 20 * scale} L ${p1.x} ${p1.y - 20 * scale}`}
        stroke={COLORS.text}
        strokeWidth={2 * scale}
        fill="none"
      />

      {/* Labels */}
      {showLabels && (
        <>
          {/* Label a (bottom) */}
          <text
            x={legA / 2}
            y={30 * scale}
            fontSize={32 * scale}
            fill={COLORS.primary}
            textAnchor="middle"
            fontWeight="bold"
          >
            {a || 'a'}
          </text>

          {/* Label b (left) */}
          <text
            x={-30 * scale}
            y={-legB / 2}
            fontSize={32 * scale}
            fill={COLORS.secondary}
            textAnchor="middle"
            dominantBaseline="middle"
            fontWeight="bold"
          >
            {b || 'b'}
          </text>

          {/* Label c (hypotenuse) */}
          <text
            x={legA / 2 + 20 * scale}
            y={-legB / 2 - 20 * scale}
            fontSize={32 * scale}
            fill={COLORS.accent}
            textAnchor="middle"
            dominantBaseline="middle"
            fontWeight="bold"
          >
            {c || 'c'}
          </text>
        </>
      )}
    </svg>
  );
};

const SquareOnSide: React.FC<{ side: 'a' | 'b' | 'c'; progress: number; scale: number; label: string; color: string; }> = ({ side, progress, scale, label, color }) => {
  const legA = 200 * scale;
  const legB = 150 * scale;
  const hypotenuse = Math.sqrt(Math.pow(legA, 2) + Math.pow(legB, 2));

  let points = '';
  let transform = '';
  let size = 0;

  if (side === 'a') {
    size = legA;
    // Square on bottom side
    points = `0,0 ${size},0 ${size},${size} 0,${size}`;
    transform = `translate(0, 0)`;
  } else if (side === 'b') {
    size = legB;
    // Square on left side
    points = `0,0 ${-size},0 ${-size},${-size} 0,${-size}`;
    transform = `translate(0, 0)`;
  } else if (side === 'c') {
    size = hypotenuse;
    // Square on hypotenuse (requires rotation)
    // Angle of hypotenuse
    const angle = Math.atan2(legB, legA);
    // Center of hypotenuse
    const cx = legA / 2;
    const cy = -legB / 2;

    // We construct the square relative to the hypotenuse line
    // This is a simplified visual representation
    const dx = (legA / hypotenuse) * size;
    const dy = (legB / hypotenuse) * size;

    const p1 = { x: 0, y: 0 };
    const p2 = { x: legA, y: 0 };
    const p3 = { x: legA - dy, y: -dx };
    const p4 = { x: -dy, y: -dx };

    points = `${p1.x},${p1.y} ${p2.x},${p2.y} ${p3.x},${p3.y} ${p4.x},${p4.y}`;
  }

  const opacity = Math.min(progress * 2, 1);
  const scaleAnim = Math.min(progress, 1);

  return (
    <g transform={transform} opacity={opacity} style={{ transformOrigin: 'center' }}>
      <polygon
        points={points}
        fill={color}
        fillOpacity={0.3}
        stroke={color}
        strokeWidth={3 * scale}
        transform={`scale(${scaleAnim})`}
        transformOrigin={side === 'c' ? 'center' : '0 0'}
      />
      {progress > 0.8 && (
        <text
          x={side === 'a' ? size / 2 : side === 'b' ? -size / 2 : legA / 2 - (legB/hypotenuse)*size/2}
          y={side === 'a' ? size / 2 : side === 'b' ? -size / 2 : -legB / 2 - (legA/hypotenuse)*size/2}
          fontSize={24 * scale}
          fill={color}
          textAnchor="middle"
          dominantBaseline="middle"
          fontWeight="bold"
        >
          {label}
        </text>
      )}
    </g>
  );
};

