// --- Types & Interfaces ---
type MathFunction = (x: number) => number;

type GraphProps = {
  func: MathFunction;
  color: string;
  range: number;
  scaleX: number;
  scaleY: number;
  opacity: number;
  strokeWidth: number;
};

type TextProps = {
  children: React.ReactNode;
  style?: React.CSSProperties;
  frame: number;
  delay: number;
};

// --- Helper Components ---

const FadeInText: React.FC<TextProps> = ({ children, style, frame, delay }) => {
  const { fps } = useVideoConfig();
  const progress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 200 },
  });

  const opacity = interpolate(progress, [0, 1], [0, 1], {
    extrapolateRight: 'clamp',
  });

});

const Graph: React.FC<GraphProps> = ({ func, color, range, scaleX, scaleY, opacity, strokeWidth }) => {
  const points = React.useMemo(() => {
    const pts: string[] = [];
    const step = 0.1;
    for (let x = -range; x <= range; x += step) {
      const y = func(x);
      const screenX = 960 + x * scaleX;
      const screenY = 540 - y * scaleY;
      pts.push(`${screenX},${screenY}`);
    }
    return pts.join(' ');
  }, [func, range, scaleX, scaleY]);

  return (
    <svg
      width={1920}
      height={1080}
      style={{ position: 'absolute', top: 0, left: 0, opacity }}
    >
      <path
        d={`M ${points}`}
        fill="none"
        stroke={color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
};

